//! Typosquat detection: distance to popular package names.
//!
//! The candidate lists are ranked seeds, parsed offline from `data/`. npm,
//! crates.io, NuGet, and PyPI are generated from each registry's download
//! ranking; the rest are curated because no honest ranking endpoint exists.

/// Provisional seed list. Keep lowercase, sorted by hand not required.
const MIN_NAME_LEN: usize = 4;

/// npm candidates, ranked by weekly downloads. Generated by
/// `scripts/refresh-popular-npm.py`; see `data/popular-npm.txt`.
pub fn popular_npm() -> &'static [&'static str] {
    static LIST: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();
    seed(&LIST, include_str!("../data/popular-npm.txt"))
}

/// Parse a generated seed file once. `#` lines are the generation header.
fn seed(
    list: &'static std::sync::OnceLock<Vec<&'static str>>,
    text: &'static str,
) -> &'static [&'static str] {
    list.get_or_init(|| {
        text.lines()
            .map(str::trim)
            .filter(|line| !line.is_empty() && !line.starts_with('#'))
            .collect()
    })
}

/// Provisional PyPI seed, same caveat as the npm list: curated, not ranked.
/// PyPI candidates, ranked by 30-day downloads. Generated by
/// `scripts/refresh-popular-seeds.py`; see `data/popular-pypi.txt`.
pub fn popular_pypi() -> &'static [&'static str] {
    static LIST: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();
    seed(&LIST, include_str!("../data/popular-pypi.txt"))
}

/// Provisional crates.io seed. Crate names are case-sensitive but effectively
/// lowercase in practice; the comparison lowercases anyway.
/// crates.io candidates, ranked by all-time downloads. Generated by
/// `scripts/refresh-popular-seeds.py`; see `data/popular-crates.txt`.
pub fn popular_crates() -> &'static [&'static str] {
    static LIST: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();
    seed(&LIST, include_str!("../data/popular-crates.txt"))
}

