/// A popular name that `name` is suspiciously close to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Suspect<'a> {
    pub candidate: &'a str,
    pub distance: usize,
    /// True when the names differ only by lookalike characters (`0`/`o`, `rn`/`m`).
    pub homoglyph: bool,
    /// True when the candidate came from the caller's lockfile, not the seed.
    pub local: bool,
}

/// Finds the closest popular name, ignoring exact matches.
///
/// A real popular package is never a suspect of itself, so an exact match
/// returns `None` instead of a distance-0 hit.
/// Finds the closest name among the seed and the caller's own dependencies.
///
/// `local` is the set of package names already trusted by the caller (the
/// base lockfile). A package that is itself well known is never flagged for
/// resembling something nearby: `preact` is not a typo of `react`.
pub fn closest<'a>(name: &str, popular: &'a [&'a str], local: &'a [String]) -> Option<Suspect<'a>> {
    let needle = name.to_ascii_lowercase();
    // Names this short sit within two edits of half the registry; reporting
    // them is pure noise.
    if needle.chars().count() < MIN_NAME_LEN {
        return None;
    }
    let known = popular.iter().any(|candidate| *candidate == needle)
        || local
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(&needle));
    if known {
        return None;
    }

    let normalized = normalize(name);
    popular
        .iter()
        .map(|candidate| (*candidate, false))
        .chain(local.iter().map(|candidate| (candidate.as_str(), true)))
        .filter(|(candidate, _)| candidate.chars().count() >= MIN_NAME_LEN)
        .map(|(candidate, local)| {
            let folded = candidate.to_ascii_lowercase();
            let candidate_normalized = normalize(candidate);
            let homoglyph = candidate_normalized == normalized && folded != needle;
            let distance = if homoglyph {
                0
            } else if reordered_tokens(&normalized, &candidate_normalized) {
                // `dateutil-python` and `python-dateutil` are one paste away;
                // edit distance calls them far apart because every token moved.
                1
            } else {
                // Adjacent transpositions are a common typo; count them as one
                // edit so an old lookalike is not dismissed as a weak match.
                damerau_levenshtein(&normalized, &candidate_normalized)
            };
            Suspect {
                candidate,
                distance,
                homoglyph,
                local,
            }
        })
        .filter(|suspect| suspect.distance <= 2)
        .min_by(|a, b| {
            a.distance
                .cmp(&b.distance)
                // On a tie, the dependency you already trust is more actionable.
                .then_with(|| b.local.cmp(&a.local))
                .then_with(|| a.candidate.cmp(b.candidate))
        })
}

/// Folds lookalike characters so `1odash`, `pаypal` (Cyrillic а), and
/// `ｌｏｄａｓｈ` (fullwidth) compare like their ASCII originals.
/// The same separator-delimited tokens in a different order. A single token
/// cannot reorder, so this never fires on a plain rename.
fn reordered_tokens(left: &str, right: &str) -> bool {
    if left == right {
        return false;
    }
    fn split(value: &str) -> Vec<&str> {
        value
            .split(['-', '_', '.'])
            .filter(|token| !token.is_empty())
            .collect()
    }
    let (mut left_tokens, mut right_tokens) = (split(left), split(right));
    if left_tokens.len() < 2 || left_tokens.len() != right_tokens.len() {
        return false;
    }
    left_tokens.sort_unstable();
    right_tokens.sort_unstable();
    left_tokens == right_tokens
}

pub fn normalize(name: &str) -> String {
    name.chars()
        .flat_map(char::to_lowercase)
        .map(fold_confusable)
        .collect::<String>()
        .replace("rn", "m")
        .chars()
        .map(|c| match c {
            '0' => 'o',
            '1' => 'l',
            '3' => 'e',
            '5' => 's',
            '7' => 't',
            'i' => 'l',
            other => other,
        })
        .collect()
}

/// Common Cyrillic/Greek lookalikes and fullwidth ASCII. A registry that
/// accepts these should not get a free pass just because the glyph is not
/// ASCII; unknown characters are left alone rather than guessed.
fn fold_confusable(c: char) -> char {
    let code = c as u32;
    if (0xFF01..=0xFF5E).contains(&code)
        && let Some(ascii) = char::from_u32(code - 0xFEE0)
    {
        return ascii;
    }
    match c {
        'а' => 'a',
        'е' => 'e',
        'о' => 'o',
        'р' => 'p',
        'с' => 'c',
        'х' => 'x',
        'у' => 'y',
        'і' | 'ї' | 'ı' => 'i',
        'ѕ' => 's',
        'ј' | 'ȷ' => 'j',
        'ԁ' => 'd',
        'һ' => 'h',
        'ӏ' => 'l',
        'ԛ' => 'q',
        'ԝ' => 'w',
        'ɡ' => 'g',
        'α' => 'a',
        'ε' => 'e',
        'ι' => 'i',
        'κ' => 'k',
        'ν' => 'v',
        'ο' => 'o',
        'ρ' => 'p',
        'τ' => 't',
        'υ' => 'u',
        'χ' => 'x',
        'ω' => 'w',
        'γ' => 'y',
        other => other,
    }
}

/// Optimal-string-alignment Damerau–Levenshtein distance: adjacent
/// transpositions count as one edit, substitutions as one.
pub fn damerau_levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut distance = vec![vec![0usize; b.len() + 1]; a.len() + 1];
    for (i, row) in distance.iter_mut().enumerate() {
        row[0] = i;
    }
    for (j, cell) in distance[0].iter_mut().enumerate() {
        *cell = j;
    }
    for i in 1..=a.len() {
        for j in 1..=b.len() {
            let cost = usize::from(a[i - 1] != b[j - 1]);
            let mut value = (distance[i - 1][j] + 1)
                .min(distance[i][j - 1] + 1)
                .min(distance[i - 1][j - 1] + cost);
            if i > 1 && j > 1 && a[i - 1] == b[j - 2] && a[i - 2] == b[j - 1] {
                value = value.min(distance[i - 2][j - 2] + 1);
            }
            distance[i][j] = value;
        }
    }
    distance[a.len()][b.len()]
}

pub fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() {
        return b.len();
    }
    if b.is_empty() {
        return a.len();
    }

    let mut previous: Vec<usize> = (0..=b.len()).collect();
    let mut current = vec![0usize; b.len() + 1];

    for (i, a_char) in a.iter().enumerate() {
        current[0] = i + 1;
        for (j, b_char) in b.iter().enumerate() {
            let substitution = previous[j] + usize::from(a_char != b_char);
            let insertion = current[j] + 1;
            let deletion = previous[j + 1] + 1;
            current[j + 1] = substitution.min(insertion).min(deletion);
        }
        std::mem::swap(&mut previous, &mut current);
    }

    previous[b.len()]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pypi_seed_is_clean() {
        let mut sorted = popular_pypi().to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), popular_pypi().len(), "duplicate PyPI names");
        assert!(
            popular_pypi()
                .iter()
                .all(|name| *name == name.to_ascii_lowercase()),
            "PyPI seed names must be lowercase"
        );
        for name in ["requests", "numpy", "django", "pydantic"] {
            assert!(popular_pypi().contains(&name), "missing {name}");
        }
    }

    #[test]
    fn composer_seed_is_clean() {
        let mut sorted = POPULAR_COMPOSER.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(
            sorted.len(),
            POPULAR_COMPOSER.len(),
            "duplicate Composer names"
        );
        for name in ["monolog/monolog", "guzzlehttp/guzzle", "symfony/console"] {
            assert!(POPULAR_COMPOSER.contains(&name), "missing {name}");
        }
    }

    #[test]
    fn maven_seed_is_clean() {
        let mut sorted = POPULAR_MAVEN.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), POPULAR_MAVEN.len(), "duplicate Maven ids");
        for name in ["junit:junit", "org.slf4j:slf4j-api"] {
            assert!(POPULAR_MAVEN.contains(&name), "missing {name}");
        }
    }

    #[test]
    fn nuget_seed_is_clean() {
        let mut sorted = popular_nuget().to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), popular_nuget().len(), "duplicate NuGet ids");
        for name in ["newtonsoft.json", "serilog", "xunit"] {
            assert!(popular_nuget().contains(&name), "missing {name}");
        }
    }

    #[test]
    fn the_sha_family_is_not_a_typo_of_itself() {
        for name in ["sha1", "sha2", "sha3"] {
            assert!(
                closest(name, popular_crates(), &[]).is_none(),
                "{name} must be recognised as a real crate family"
            );
        }
    }

    #[test]
    fn rubygems_seed_is_clean() {
        let mut sorted = POPULAR_RUBYGEMS.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), POPULAR_RUBYGEMS.len(), "duplicate gem names");
        for name in ["rails", "rack", "rake", "rspec"] {
            assert!(POPULAR_RUBYGEMS.contains(&name), "missing {name}");
        }
    }

    #[test]
    fn jsr_seed_is_clean() {
        let mut sorted = POPULAR_JSR.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), POPULAR_JSR.len(), "duplicate JSR names");
        for name in ["@std/assert", "@std/path", "@oak/oak"] {
            assert!(POPULAR_JSR.contains(&name), "missing {name}");
        }
    }

    #[test]
    fn crates_seed_is_clean() {
        let mut sorted = popular_crates().to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(
            sorted.len(),
            popular_crates().len(),
            "duplicate crate names"
        );
        for name in [
            "serde", "tokio", "clap", "rand", "inotify", "rustix", "shlex",
        ] {
            assert!(popular_crates().contains(&name), "missing {name}");
        }
    }

    #[test]
    fn go_seed_is_clean() {
        let mut sorted = POPULAR_GO.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), POPULAR_GO.len(), "duplicate Go modules");
        for name in [
            "github.com/gin-gonic/gin",
            "golang.org/x/net",
            "k8s.io/client-go",
        ] {
            assert!(POPULAR_GO.contains(&name), "missing {name}");
        }
    }

    #[test]
    fn popular_list_is_clean() {
        let popular = popular_npm();
        let mut sorted = popular.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), popular.len(), "duplicate popular names");
        assert!(
            popular
                .iter()
                .all(|name| *name == name.to_ascii_lowercase()),
            "popular names must be lowercase"
        );
        for name in [
            "express",
            "react",
            "lodash",
            "axios",
            "typescript",
            "cross-env",
            "preact",
            "moment",
        ] {
            assert!(popular.contains(&name), "missing popular name {name}");
        }
    }

    #[test]
    fn cmake_is_not_a_typo_of_image() {
        // cmake is a real build-tool crate two edits from `image`. It used to
        // make dep-vet's own `dependency-added` check WARN on zstd-sys.
        assert_eq!(closest("cmake", popular_crates(), &[]), None);
    }

    #[test]
    fn inotify_is_not_a_typo_of_notify() {
        assert_eq!(closest("inotify", popular_crates(), &[]), None);
    }

    #[test]
    fn legitimate_neighbours_are_not_suspects() {
        // Real crates that sit one or two edits from another seed entry.
        for name in [
            "inotify", "rustix", "shlex", "notify", "rustls", "sqlx", "cmake",
        ] {
            assert_eq!(
                closest(name, popular_crates(), &[]),
                None,
                "{name} must be a known candidate"
            );
        }
    }

    #[test]
    fn exact_popular_name_is_not_a_suspect() {
        assert_eq!(closest("express", popular_npm(), &[]), None);
        assert_eq!(closest("Express", popular_npm(), &[]), None);
    }

    #[test]
    fn detects_single_edit_typosquat() {
        let suspect = closest("expres", popular_npm(), &[]).unwrap();
        assert_eq!(suspect.candidate, "express");
        assert_eq!(suspect.distance, 1);
        assert!(!suspect.homoglyph);
    }

    #[test]
    fn detects_two_edit_typosquat() {
        let suspect = closest("expresss", popular_npm(), &[]).unwrap();
        assert_eq!(suspect.candidate, "express");
        assert_eq!(suspect.distance, 1);
    }

    #[test]
    fn detects_digit_homoglyph() {
        let suspect = closest("1odash", popular_npm(), &[]).unwrap();
        assert_eq!(suspect.candidate, "lodash");
        assert!(suspect.homoglyph);
        assert_eq!(suspect.distance, 0);
    }

    #[test]
    fn detects_multi_char_homoglyph() {
        // "rn" folds to "m", so "mornent" normalizes to "moment".
        let suspect = closest("mornent", popular_npm(), &[]).unwrap();
        assert_eq!(suspect.candidate, "moment");
        assert!(suspect.homoglyph);
        assert_eq!(suspect.distance, 0);
    }

    #[test]
    fn finds_a_typosquat_of_a_local_dependency() {
        let local = vec!["cross-env".to_string()];
        let suspect = closest("crossenv", popular_npm(), &local).unwrap();
        assert_eq!(suspect.candidate, "cross-env");
        assert!(suspect.local);
        assert_eq!(suspect.distance, 1);
    }

    #[test]
    fn local_dependency_matching_is_case_insensitive() {
        let local = vec!["Cross-Env".to_string()];
        assert_eq!(closest("cross-env", popular_npm(), &local), None);
    }

    #[test]
    fn a_known_package_is_not_a_typo_of_a_similar_local_one() {
        // preact is in the seed; react in the lockfile must not make it a hit.
        let local = vec!["react".to_string()];
        assert_eq!(closest("preact", popular_npm(), &local), None);
    }

    #[test]
    fn short_names_are_not_flagged() {
        assert_eq!(closest("ms", popular_npm(), &[]), None);
        assert_eq!(closest("tmpl", popular_npm(), &[]), None);
    }

    #[test]
    fn unrelated_name_has_no_suspect() {
        assert_eq!(closest("zzzzzzzzzzzzzzzz", popular_npm(), &[]), None);
        assert_eq!(closest("dep-vet", popular_npm(), &[]), None);
    }

    #[test]
    fn prefers_the_closest_candidate() {
        let suspect = closest("reactx", popular_npm(), &[]).unwrap();
        assert_eq!(suspect.candidate, "react");
    }

    #[test]
    fn empty_name_is_not_a_suspect() {
        assert_eq!(closest("", popular_npm(), &[]), None);
    }

    #[test]
    fn adjacent_transpositions_are_one_edit() {
        assert_eq!(damerau_levenshtein("lodahs", "lodash"), 1);
        assert_eq!(damerau_levenshtein("axois", "axios"), 1);
        assert_eq!(damerau_levenshtein("lodash", "lodash"), 0);
        assert_eq!(damerau_levenshtein("consoel", "console"), 1);
        assert_eq!(damerau_levenshtein("kitten", "sitting"), 3);
    }

    #[test]
    fn unicode_confusables_fold_to_ascii() {
        assert_eq!(normalize("pаypal"), "paypal");
        assert_eq!(normalize("рreact"), "preact");
        assert_eq!(normalize("ｌｏｄａｓｈ"), "lodash");
        assert_eq!(normalize("PAYPAL"), "paypal");
    }

    #[test]
    fn a_cyrillic_lookalike_is_a_homoglyph_suspect() {
        let suspect = closest("рreact", &["preact"], &[]).unwrap();
        assert_eq!(suspect.candidate, "preact");
        assert_eq!(suspect.distance, 0);
        assert!(suspect.homoglyph, "{suspect:?}");
    }

    #[test]
    fn generated_seeds_are_large_and_clean() {
        let seeds = [
            ("npm", popular_npm(), 500),
            ("crates", popular_crates(), 400),
            ("nuget", popular_nuget(), 400),
            ("pypi", popular_pypi(), 400),
        ];
        for (label, seed, floor) in seeds {
            assert!(
                seed.len() >= floor,
                "{label} seed shrank to {} names",
                seed.len()
            );
            let mut sorted = seed.to_vec();
            sorted.sort_unstable();
            sorted.dedup();
            assert_eq!(sorted.len(), seed.len(), "{label} seed has duplicates");
            assert!(
                seed.iter().all(|name| *name == name.to_ascii_lowercase()),
                "{label} seed must be lowercase"
            );
        }
    }

    #[test]
    fn the_regression_dataset_meets_the_precision_and_recall_floor() {
        struct Case {
            ecosystem: &'static str,
            name: &'static str,
            target: &'static str,
            kind: &'static str,
            note: &'static str,
        }

        let cases: Vec<Case> = include_str!("../tests/fixtures/typosquat-cases.tsv")
            .lines()
            .filter(|line| !line.trim().is_empty() && !line.starts_with('#'))
            .filter_map(|line| {
                let mut fields = line.splitn(5, '\t');
                Some(Case {
                    ecosystem: fields.next()?,
                    name: fields.next()?,
                    target: fields.next()?,
                    kind: fields.next()?,
                    note: fields.next().unwrap_or(""),
                })
            })
            .collect();
        assert!(cases.len() >= 40, "the dataset shrank: {}", cases.len());

        let seed = |ecosystem: &str| -> &'static [&'static str] {
            match ecosystem {
                "npm" => popular_npm(),
                "pypi" => popular_pypi(),
                "crates" => popular_crates(),
                "go" => POPULAR_GO,
                "jsr" => POPULAR_JSR,
                "rubygems" => POPULAR_RUBYGEMS,
                "nuget" => popular_nuget(),
                "maven" => POPULAR_MAVEN,
                "composer" => POPULAR_COMPOSER,
                other => panic!("unknown ecosystem in dataset: {other}"),
            }
        };

        let mut true_positives = 0;
        let mut false_positives = 0;
        let mut false_negatives = 0;
        let mut known_true = 0;
        let mut known_total = 0;
        for case in &cases {
            let suspect = closest(case.name, seed(case.ecosystem), &[]);
            if case.kind == "legit" {
                if let Some(suspect) = suspect {
                    false_positives += 1;
                    eprintln!(
                        "false positive: {} {} -> {} at distance {} ({})",
                        case.ecosystem, case.name, suspect.candidate, suspect.distance, case.note
                    );
                }
                continue;
            }
            if case.kind == "known" {
                known_total += 1;
            }
            match suspect {
                Some(suspect) if suspect.candidate == case.target => {
                    true_positives += 1;
                    if case.kind == "known" {
                        known_true += 1;
                    }
                }
                other => {
                    false_negatives += 1;
                    eprintln!(
                        "miss: {} {} expected {} got {:?} ({})",
                        case.ecosystem,
                        case.name,
                        case.target,
                        other.map(|suspect| (
                            suspect.candidate,
                            suspect.distance,
                            suspect.homoglyph
                        )),
                        case.note
                    );
                }
            }
        }
        let precision = true_positives as f64 / (true_positives + false_positives) as f64;
        let recall = true_positives as f64 / (true_positives + false_negatives) as f64;
        eprintln!(
            "typosquat dataset: {} cases, precision {:.3}, recall {:.3}, known {}/{}",
            cases.len(),
            precision,
            recall,
            known_true,
            known_total
        );
        assert!(precision >= 0.95, "precision {precision:.3}");
        assert!(recall >= 0.95, "recall {recall:.3}");
        assert_eq!(
            known_true, known_total,
            "every documented attack must be caught"
        );
    }

    #[test]
    fn levenshtein_basics() {
        assert_eq!(levenshtein("", ""), 0);
        assert_eq!(levenshtein("abc", ""), 3);
        assert_eq!(levenshtein("", "abc"), 3);
        assert_eq!(levenshtein("abc", "abc"), 0);
        assert_eq!(levenshtein("kitten", "sitting"), 3);
        assert_eq!(levenshtein("flaw", "lawn"), 2);
    }

    #[test]
    fn levenshtein_handles_unicode() {
        assert_eq!(levenshtein("café", "cafe"), 1);
        assert_eq!(levenshtein("日本", "日木"), 1);
    }
}
